import math

def trapezium(f, a, b, n):
    h = (b - a) / n
    total = 0.0
    for i in range(n):
        left = a + i * h
        total += h * (f(left) + f(left + h)) / 2
    return total

def phi(x):
    # the standard normal density
    return math.exp(-x * x / 2) / math.sqrt(2 * math.pi)

def prob_within(z, n):
    # chance a standard normal lands in [-z, z], using n strips
    return trapezium(phi, -z, z, n)
